/**
 * 实验编辑页面 — 专家级增强版
 * 功能：基本信息编辑 + 材料/设备管理 + 可视化参数编辑 + 目标管理 + 时间计划
 */
import { useState, useEffect } from 'react'
import { useTranslation } from 'react-i18next'
import { useParams, useNavigate, Link } from 'react-router-dom'
import { ArrowLeft, Save, FlaskConical, CalendarDays, Plus, X, Settings, Wrench, ClipboardList, Trash2, AlertCircle } from 'lucide-react'
import { useExperiment } from '@/hooks/useQueries'
import { experimentApi } from '@/api/experiment'
import { useQueryClient } from '@tanstack/react-query'
import { Button, Input, Textarea, Card, CardContent, Badge } from '@/components/ui'
import { Skeleton } from '@/components/ui/Common'
import { cn } from '@/lib/utils'
import type { ExperimentCreatePayload } from '@/api/experiment'

export default function ExperimentEditPage() {
  const { t } = useTranslation()
  const { id } = useParams<{ id: string }>()
  const navigate = useNavigate()
  const qc = useQueryClient()
  const experimentId = Number(id)

  const { data: experiment, isLoading } = useExperiment(experimentId)

  const [form, setForm] = useState<ExperimentCreatePayload>({
    title: '',
    description: '',
    formula_id: undefined,
    objectives: [],
    methodology: '',
    parameters: {},
    materials: [],
    equipment: [],
    start_date: '',
    end_date: '',
  })

  const [objectiveInput, setObjectiveInput] = useState('')
  const [materialInput, setMaterialInput] = useState('')
  const [equipmentInput, setEquipmentInput] = useState('')
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState('')
  const [activeTab, setActiveTab] = useState<'basic' | 'params' | 'materials'>('basic')

  // 参数编辑状态
  const [paramKey, setParamKey] = useState('')
  const [paramValue, setParamValue] = useState('')

  useEffect(() => {
    if (experiment) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setForm({
        title: experiment.title,
        description: experiment.description || '',
        formula_id: experiment.formulaId || undefined,
        objectives: experiment.objectives || [],
        methodology: experiment.methodology || '',
        parameters: (experiment.parameters || {}) as Record<string, unknown>,
        materials: experiment.materials || [],
        equipment: experiment.equipment || [],
        start_date: experiment.start_date ? experiment.start_date.slice(0, 10) : '',
        end_date: experiment.end_date ? experiment.end_date.slice(0, 10) : '',
      })
    }
  }, [experiment])

  const updateField = <K extends keyof ExperimentCreatePayload>(key: K, value: ExperimentCreatePayload[K]) => {
    setForm((prev) => ({ ...prev, [key]: value }))
  }

  const addObjective = () => {
    const trimmed = objectiveInput.trim()
    if (trimmed && !(form.objectives || []).includes(trimmed)) {
      updateField('objectives', [...(form.objectives || []), trimmed])
      setObjectiveInput('')
    }
  }

  const removeObjective = (idx: number) => {
    updateField('objectives', (form.objectives || []).filter((_, i) => i !== idx))
  }

  const addMaterial = () => {
    const trimmed = materialInput.trim()
    if (trimmed) {
      updateField('materials', [...(form.materials || []), { name: trimmed, quantity: '', unit: '' }])
      setMaterialInput('')
    }
  }

  const removeMaterial = (idx: number) => {
    updateField('materials', (form.materials || []).filter((_, i) => i !== idx))
  }

  const updateMaterial = (idx: number, field: string, value: string) => {
    const materials = [...(form.materials || [])]
    materials[idx] = { ...materials[idx], [field]: value }
    updateField('materials', materials)
  }

  const addEquipment = () => {
    const trimmed = equipmentInput.trim()
    if (trimmed) {
      updateField('equipment', [...(form.equipment || []), { name: trimmed, quantity: '', unit: '个' }])
      setEquipmentInput('')
    }
  }

  const removeEquipment = (idx: number) => {
    updateField('equipment', (form.equipment || []).filter((_, i) => i !== idx))
  }

  const addParam = () => {
    if (!paramKey.trim()) return
    const params = { ...(form.parameters || {}) }
    params[paramKey.trim()] = paramValue
    updateField('parameters', params)
    setParamKey('')
    setParamValue('')
  }

  const removeParam = (key: string) => {
    const params = { ...(form.parameters || {}) }
    delete params[key]
    updateField('parameters', params)
  }

  const validate = (): boolean => {
    if (!form.title.trim()) {
      setError(t('pages.experimentForm.titleRequired'))
      return false
    }
    setError('')
    return true
  }

  const handleSave = async () => {
    if (!validate()) return
    setSaving(true)
    setError('')
    try {
      await experimentApi.update(experimentId, form)
      qc.invalidateQueries({ queryKey: ['experiment', experimentId] })
      qc.invalidateQueries({ queryKey: ['experiments'] })
      navigate(`/experiments/${experimentId}`)
    } catch (err: any) {
      setError(err?.response?.data?.detail || t('pages.experimentForm.saveFailed'))
    } finally {
      setSaving(false)
    }
  }

  const formCompleteness = (() => {
    let filled = 0
    const total = 7
    if (form.title.trim()) filled++
    if (form.description?.trim()) filled++
    if (form.objectives && form.objectives.length > 0) filled++
    if (form.methodology?.trim()) filled++
    if (form.parameters && Object.keys(form.parameters).length > 0) filled++
    if (form.materials && form.materials.length > 0) filled++
    if (form.start_date && form.end_date) filled++
    return { filled, total, percent: Math.round((filled / total) * 100) }
  })()

  const tabs = [
    { key: 'basic' as const, labelKey: 'pages.experimentForm.basicInfo', icon: FlaskConical },
    { key: 'params' as const, labelKey: 'pages.experimentForm.params', icon: Settings },
    { key: 'materials' as const, labelKey: 'pages.experimentForm.materialsEquipment', icon: ClipboardList },
  ]

  if (isLoading) {
    return (
      <div className="max-w-[1600px] mx-auto space-y-[var(--space-apple-md)]">
        <Skeleton className="h-8 w-1/4" />
        <Skeleton className="h-64 w-full" />
      </div>
    )
  }

  if (!experiment) {
    return (
      <div className="max-w-[1600px] mx-auto text-center py-20">
        <p className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{t('pages.experimentForm.experimentNotExist')}</p>
        <Link to="/experiments" className="text-[var(--color-primary-text)] text-sm mt-2 inline-block">{t('pages.experimentForm.backToList')}</Link>
      </div>
    )
  }

  const isEditable = experiment.status === 'planned' || experiment.status === 'in_progress'

  if (!isEditable) {
    return (
      <div className="max-w-[1600px] mx-auto text-center py-20">
        <p className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{t('pages.experimentForm.notEditable')}</p>
        <Link to={`/experiments/${experimentId}`} className="text-[var(--color-primary-text)] text-sm mt-2 inline-block">{t('pages.experimentForm.backToDetail')}</Link>
      </div>
    )
  }

  return (
    <div className="max-w-[1600px] mx-auto px-[var(--space-apple-md)] sm:px-6 lg:px-8 space-y-6">
      {/* 头部 */}
      <div className="flex items-center justify-between">
        {/* A-47：这一页原本完全没有 h1 —— 只有「返回详情」和「保存修改」两个按钮，
            屏幕阅读器用户进入后拿不到任何页面主题。补一个可见的 h1 作为页面标题。 */}
        <div className="flex items-center gap-[var(--space-apple-sm)]">
          <button
            onClick={() => navigate(`/experiments/${experimentId}`)}
            className="flex items-center gap-2 text-sm text-[var(--text-muted)] hover:text-[var(--text-primary)] transition-colors"
          >
            <ArrowLeft size={16} />
            {t('pages.experimentForm.backToDetail')}
          </button>
          <h1 className="text-xl font-semibold leading-snug tracking-tight text-[var(--text-primary)]">{t('pages.experimentForm.titleEdit')}</h1>
        </div>
        <div className="flex items-center gap-[var(--space-apple-sm)]">
          <div className="flex items-center gap-2">
            <div className="w-16 h-1.5 bg-[var(--bg-tertiary)] rounded-[var(--radius-pill)] overflow-hidden">
              <div className="h-full bg-[var(--color-primary-container)]0 rounded-[var(--radius-pill)] transition-all duration-500" style={{ width: `${formCompleteness.percent}%` }} />
            </div>
            <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] font-medium">{formCompleteness.percent}%</span>
          </div>
          <Button
            onClick={handleSave}
            loading={saving}
            icon={<Save size={14} />}
            className="bg-[var(--color-primary)] hover:bg-[var(--color-primary)] shadow-primary-600/25"
          >
            {t('pages.experimentForm.saveChanges')}
          </Button>
        </div>
      </div>

      {error && (
        <div className="flex items-center gap-2 px-[var(--space-apple-md)] py-[var(--space-apple-md)] rounded-[var(--radius-Apple-sm)] bg-[var(--color-error-container)] border border-[var(--color-error-border)] dark:border-[var(--color-error)] text-[var(--color-error-text)] dark:text-[var(--color-error-text)] text-sm">
          <AlertCircle size={16} />{error}
        </div>
      )}

      {/* 标签导航 */}
      <div className="flex gap-1 bg-[var(--bg-tertiary)] rounded-[var(--radius-Apple-md)] p-1">
        {tabs.map((tab) => {
          const Icon = tab.icon
          return (
            <button
              key={tab.key}
              onClick={() => setActiveTab(tab.key)}
              className={cn(
                'flex-1 flex items-center justify-center gap-2 px-[var(--space-apple-md)] py-2 rounded-[var(--radius-Apple-sm)] text-sm font-medium transition-all',
                activeTab === tab.key
                  ? 'bg-[var(--bg-secondary)] dark:bg-[var(--bg-secondary)] text-[var(--text-primary)] shadow-sm'
                  : 'text-[var(--text-muted)] hover:text-[var(--text-primary)]',
              )}
            >
              <Icon size={14} />
              {t(tab.labelKey)}
            </button>
          )
        })}
      </div>

      {/* 基本信息 */}
      {activeTab === 'basic' && (
        <div className="space-y-6">
          <Card>
            <CardContent className="space-y-5">
              <div className="flex items-center gap-2 text-[var(--text-primary)] font-semibold">
                <FlaskConical size={18} />
                {t('pages.experimentForm.basicInfo')}
              </div>

              <div>
                <label className="block text-sm font-medium text-[var(--text-primary)] mb-1.5">
                  {t('pages.experimentForm.experimentTitle')} <span className="text-[var(--color-error-text)]0">*</span>
                </label>
                <Input
                  value={form.title}
                  onChange={(e) => updateField('title', e.target.value)}
                  placeholder={t('pages.experimentForm.experimentTitlePlaceholder')}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-[var(--text-primary)] mb-1.5">{t('pages.experimentForm.experimentDescription')}</label>
                <Textarea
                  value={form.description}
                  onChange={(e) => updateField('description', e.target.value)}
                  placeholder={t('pages.experimentForm.experimentDescriptionPlaceholder')}
                  rows={3}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-[var(--text-primary)] mb-1.5">{t('pages.experimentForm.methodology')}</label>
                <Textarea
                  value={form.methodology}
                  onChange={(e) => updateField('methodology', e.target.value)}
                  placeholder={t('pages.experimentForm.methodologyPlaceholder')}
                  rows={4}
                />
              </div>
            </CardContent>
          </Card>

          {/* 实验目标 */}
          <Card>
            <CardContent className="space-y-[var(--space-apple-md)]">
              <div className="text-[var(--text-primary)] font-semibold">{t('pages.experimentForm.objectives')}</div>

              {form.objectives && form.objectives.length > 0 && (
                <div className="flex flex-wrap gap-2">
                  {form.objectives.map((obj, i) => (
                    <Badge key={i} variant="info" className="gap-1">
                      {obj}
                      <button onClick={() => removeObjective(i)} className="ml-0.5 hover:text-[var(--color-error-text)]0">
                        <X size={10} />
                      </button>
                    </Badge>
                  ))}
                </div>
              )}

              <div className="flex gap-2">
                <Input
                  value={objectiveInput}
                  onChange={(e) => setObjectiveInput(e.target.value)}
                  onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); addObjective() } }}
                  placeholder={t('pages.experimentForm.objectivePlaceholder')}
                  className="flex-1"
                />
                <Button onClick={addObjective} disabled={!objectiveInput.trim()} variant="secondary" size="sm">
                  {t('pages.experimentForm.add')}
                </Button>
              </div>
            </CardContent>
          </Card>

          {/* 时间计划 */}
          <Card>
            <CardContent className="space-y-5">
              <div className="flex items-center gap-2 text-[var(--text-primary)] font-semibold">
                <CalendarDays size={18} />
                {t('pages.experimentForm.schedule')}
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-[var(--text-primary)] mb-1.5">
                    {t('pages.experimentForm.startDate')}
                  </label>
                  <Input type="date" value={form.start_date} onChange={(e) => updateField('start_date', e.target.value)} />
                </div>
                <div>
                  <label className="block text-sm font-medium text-[var(--text-primary)] mb-1.5">
                    {t('pages.experimentForm.endDate')}
                  </label>
                  <Input type="date" value={form.end_date} onChange={(e) => updateField('end_date', e.target.value)} />
                </div>
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      {/* 参数编辑 */}
      {activeTab === 'params' && (
        <Card>
          <CardContent className="space-y-5">
            <div className="flex items-center gap-2 text-[var(--text-primary)] font-semibold">
              <Settings size={18} />
              {t('pages.experimentForm.params')}
            </div>

            {/* 参数表格 */}
            <div className="space-y-2">
              {(form.parameters ? Object.entries(form.parameters) : []).map(([key, value]) => (
                <div key={key} className="flex items-center gap-2 p-2 bg-[var(--bg-tertiary)]/50 rounded-[var(--radius-Apple-sm)] group">
                  <span className="text-sm font-medium text-[var(--text-primary)] min-w-[120px] truncate">{key}</span>
                  <span className="text-sm text-[var(--text-muted)] flex-1 truncate">{String(value)}</span>
                  <button
                    onClick={() => removeParam(key)}
                    className="p-1 rounded text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-[var(--color-error-text)]0 opacity-0 group-hover:opacity-100 transition-all"
                  >
                    <Trash2 size={12} />
                  </button>
                </div>
              ))}
              {(form.parameters ? Object.keys(form.parameters).length === 0 : true) && (
                <div className="text-center py-[var(--space-apple-lg)] text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{t('pages.experimentForm.noParams')}</div>
              )}
            </div>

            {/* 添加参数 */}
            <div className="flex gap-2">
              <Input
                value={paramKey}
                onChange={(e) => setParamKey(e.target.value)}
                placeholder={t('pages.experimentForm.paramName')}
                size="sm"
                className="flex-1"
              />
              <Input
                value={paramValue}
                onChange={(e) => setParamValue(e.target.value)}
                placeholder={t('pages.experimentForm.paramValue')}
                size="sm"
                className="flex-1"
              />
              <Button size="sm" onClick={addParam} disabled={!paramKey.trim()} variant="secondary">
                <Plus size={14} />
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {/* 材料与设备 */}
      {activeTab === 'materials' && (
        <div className="space-y-6">
          {/* 材料管理 */}
          <Card>
            <CardContent className="space-y-[var(--space-apple-md)]">
              <div className="flex items-center gap-2 text-[var(--text-primary)] font-semibold">
                <FlaskConical size={18} className="text-[var(--color-accent-text)]0" />
                {t('pages.experimentForm.experimentMaterials')}
              </div>

              {(form.materials || []).map((mat: any, idx: number) => (
                <div key={idx} className="flex items-center gap-2 p-[var(--space-apple-sm)] bg-[var(--bg-tertiary)]/50 rounded-[var(--radius-Apple-sm)] group">
                  <div className="flex-1 grid grid-cols-1 sm:grid-cols-3 gap-2">
                    <Input
                      value={mat.name || ''}
                      onChange={(e) => updateMaterial(idx, 'name', e.target.value)}
                      placeholder={t('pages.experimentForm.materialNamePlaceholder')}
                      size="sm"
                    />
                    <Input
                      value={mat.quantity || ''}
                      onChange={(e) => updateMaterial(idx, 'quantity', e.target.value)}
                      placeholder={t('pages.experimentForm.quantityPlaceholder')}
                      size="sm"
                    />
                    <Input
                      value={mat.unit || ''}
                      onChange={(e) => updateMaterial(idx, 'unit', e.target.value)}
                      placeholder={t('pages.experimentForm.unitPlaceholder')}
                      size="sm"
                    />
                  </div>
                  <button
                    onClick={() => removeMaterial(idx)}
                    className="p-1 rounded text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-[var(--color-error-text)]0 opacity-0 group-hover:opacity-100 transition-all"
                  >
                    <Trash2 size={14} />
                  </button>
                </div>
              ))}
              {(form.materials || []).length === 0 && (
                <div className="text-center py-4 text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{t('pages.experimentForm.noMaterials')}</div>
              )}

              <div className="flex gap-2">
                <Input
                  value={materialInput}
                  onChange={(e) => setMaterialInput(e.target.value)}
                  onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); addMaterial() } }}
                  placeholder={t('pages.experimentForm.materialPlaceholder')}
                  className="flex-1"
                />
                <Button onClick={addMaterial} disabled={!materialInput.trim()} variant="secondary" size="sm">
                  <Plus size={14} />
                </Button>
              </div>
            </CardContent>
          </Card>

          {/* 设备管理 */}
          <Card>
            <CardContent className="space-y-[var(--space-apple-md)]">
              <div className="flex items-center gap-2 text-[var(--text-primary)] font-semibold">
                <Wrench size={18} className="text-info-500" />
                {t('pages.experimentForm.experimentEquipment')}
              </div>

              {(form.equipment || []).map((eq: any, idx: number) => (
                <div key={idx} className="flex items-center gap-2 p-[var(--space-apple-sm)] bg-[var(--bg-tertiary)]/50 rounded-[var(--radius-Apple-sm)] group">
                  <span className="text-sm font-medium text-[var(--text-primary)] flex-1">{eq.name}</span>
                  <Badge variant={eq.status === 'available' ? 'success' : 'warning'} size="sm">
                    {eq.status === 'available' ? t('pages.experimentForm.equipmentStatusAvailable') : t('pages.experimentForm.equipmentStatusInUse')}
                  </Badge>
                  <button
                    onClick={() => removeEquipment(idx)}
                    className="p-1 rounded text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-[var(--color-error-text)]0 opacity-0 group-hover:opacity-100 transition-all"
                  >
                    <Trash2 size={14} />
                  </button>
                </div>
              ))}
              {(form.equipment || []).length === 0 && (
                <div className="text-center py-4 text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{t('pages.experimentForm.noEquipment')}</div>
              )}

              <div className="flex gap-2">
                <Input
                  value={equipmentInput}
                  onChange={(e) => setEquipmentInput(e.target.value)}
                  onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); addEquipment() } }}
                  placeholder={t('pages.experimentForm.equipmentPlaceholder')}
                  className="flex-1"
                />
                <Button onClick={addEquipment} disabled={!equipmentInput.trim()} variant="secondary" size="sm">
                  <Plus size={14} />
                </Button>
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      {/* 底部保存按钮 */}
      <div className="flex items-center justify-end gap-[var(--space-apple-sm)] pt-2 pb-8">
        <Link to={`/experiments/${experimentId}`}>
          <Button variant="secondary">{t('pages.experimentForm.cancelForm')}</Button>
        </Link>
        <Button
          onClick={handleSave}
          loading={saving}
          icon={<Save size={14} />}
          className="bg-[var(--color-primary)] hover:bg-[var(--color-primary)] shadow-primary-600/25"
        >
          {t('pages.experimentForm.saveChanges')}
        </Button>
      </div>
    </div>
  )
}

/**
 * 配方成分可视化组件
 * 饼图展示君臣佐使角色分布 + 柱状图展示用量分布
 */
import { useMemo } from 'react'
import { PieChart, Pie, Cell, ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip } from 'recharts'
import { getChartThemeColors, getRoleColor } from '../../../utils/chartTheme'
import { useIsDarkMode } from '@/theme'

interface Ingredient {
  name: string
  category?: string
  is_food_homology?: boolean
  dosage?: string
  role?: string
}

interface CompositionChartProps {
  ingredients: Ingredient[]
  compact?: boolean
}

function parseDosage(dosage: string): number {
  if (!dosage) return 0
  const match = /^([\d.]+)/.exec(dosage)
  if (match) return parseFloat(match[1])
  return 0
}

function getDosageUnit(dosage: string): string {
  if (!dosage) return ''
  return dosage.replace(/^[\d.]+/, '').trim() || 'g'
}

export function CompositionChart({ ingredients, compact = false }: CompositionChartProps) {
  // D-43 修复：原为 useMemo(..., []) 空依赖 —— 切主题后图表颜色不会更新
  const isDark = useIsDarkMode()
  const colors = useMemo(() => getChartThemeColors(), [isDark])
  const tooltipBg = colors.tooltipBg || 'var(--card-bg-solid, #FFFFFF)'
  const tooltipBorder = colors.tooltipBorder || 'var(--border-subtle, rgba(0,0,0,0.06))'
  const tooltipText = colors.tooltipText || 'var(--text-secondary, #6E6E73)'
  const axisColor = colors.axisColor || 'var(--text-muted, #9A9A9F)'
  const barFill = colors.barFill || 'var(--color-secondary, #0A84FF)'

  const tooltipStyle = {
    backgroundColor: tooltipBg,
    border: `1px solid ${tooltipBorder}`,
    borderRadius: '8px',
    color: tooltipText,
    fontSize: '12px',
  }

  const roleData = useMemo(() => {
    const roleMap: Record<string, number> = {}
    ingredients.forEach(ing => {
      const role = ing.role || '未分类'
      roleMap[role] = (roleMap[role] || 0) + 1
    })
    return Object.entries(roleMap).map(([name, value]) => ({
      name,
      value,
      fill: getRoleColor(name),
    }))
  }, [ingredients])

  const dosageData = useMemo(() => {
    return ingredients
      .map(ing => ({
        name: ing.name.length > 6 ? ing.name.slice(0, 6) + '...' : ing.name,
        dosage: parseDosage(ing.dosage || '0'),
        unit: getDosageUnit(ing.dosage || '0'),
      }))
      .filter(item => item.dosage > 0)
      .sort((a, b) => b.dosage - a.dosage)
      .slice(0, compact ? 5 : 10)
  }, [ingredients, compact])

  const categoryData = useMemo(() => {
    const catMap: Record<string, number> = {}
    ingredients.forEach(ing => {
      const cat = ing.category || '未分类'
      catMap[cat] = (catMap[cat] || 0) + 1
    })
    return Object.entries(catMap)
      .map(([name, value], i) => ({
        name: name.length > 8 ? name.slice(0, 8) + '...' : name,
        value,
        fill: colors.pie[i % colors.pie.length],
      }))
      .sort((a, b) => b.value - a.value)
  }, [ingredients, colors])

  const totalIngredients = ingredients.length

  if (totalIngredients === 0) {
    return (
      <div className="py-8 text-center text-[var(--text-muted)]">
        <p className="text-sm">暂无成分数据</p>
        <p className="text-xs mt-1">请先添加成分后查看分布图</p>
      </div>
    )
  }

  if (compact) {
    return (
      <div className="flex items-center gap-[var(--space-apple-sm)]">
        <div className="w-20 h-20 shrink-0">
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie rootTabIndex={-1}
                data={roleData}
                cx="50%"
                cy="50%"
                innerRadius={16}
                outerRadius={32}
                paddingAngle={2}
                dataKey="value"
              >
                {roleData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={entry.fill} />
                ))}
              </Pie>
            </PieChart>
          </ResponsiveContainer>
        </div>
        <div className="flex-1 min-w-0">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-3 gap-y-1">
            {roleData.map((entry) => (
              <div key={entry.name} className="flex items-center gap-1.5">
                <div className="w-2.5 h-2.5 rounded-[var(--radius-pill)] shrink-0" style={{ backgroundColor: entry.fill }} />
                <span className="text-xs text-[var(--text-secondary)] truncate">
                  {entry.name} ({entry.value})
                </span>
              </div>
            ))}
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-[var(--space-apple-md)]">
      {roleData.length > 0 && (
        <div>
          <h5 className="text-xs font-medium text-[var(--text-muted)] mb-2">君臣佐使分布</h5>
          <div className="flex items-center gap-4">
            <div className="w-28 h-28 shrink-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie rootTabIndex={-1}
                    data={roleData}
                    cx="50%"
                    cy="50%"
                    innerRadius={24}
                    outerRadius={44}
                    paddingAngle={3}
                    dataKey="value"
                    label={({ name, percent }) => `${name}${Math.round(percent * 100)}%`}
                    labelLine={false}
                  >
                    {roleData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={entry.fill} />
                    ))}
                  </Pie>
                  <Tooltip
                      contentStyle={tooltipStyle}
                      formatter={(value: number) => [`${value} 种 (${((value / totalIngredients) * 100).toFixed(0)}%)`, '数量']}
                    />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <div className="flex-1">
              <div className="grid grid-cols-1 sm:grid-cols-2 sm:grid-cols-3 gap-2">
                {roleData.map((entry) => (
                  <div key={entry.name} className="flex items-center gap-2 px-2 py-1.5 rounded-[var(--radius-Apple-sm)] bg-[var(--bg-tertiary)]/50">
                    <div className="w-3 h-3 rounded-[var(--radius-pill)] shrink-0" style={{ backgroundColor: entry.fill }} />
                    <div className="min-w-0">
                      <span className="text-xs font-medium text-[var(--text-primary)]">{entry.name}</span>
                      <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{entry.value} 种</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}

      {dosageData.length > 0 && (
        <div>
          <h5 className="text-xs font-medium text-[var(--text-muted)] mb-2">用量分布 (Top {dosageData.length})</h5>
          <div className="h-32">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={dosageData} layout="vertical" margin={{ left: 50, right: 16 }}>
                <XAxis type="number" tick={{ fontSize: 10, fill: axisColor }} />
                <YAxis type="category" dataKey="name" tick={{ fontSize: 10, fill: axisColor }} width={50} />
                <Tooltip
                  contentStyle={tooltipStyle}
                  formatter={(value: number, _: any, props: any) => [`${value} ${props.payload.unit || 'g'}`, '用量']}
                />
                <Bar dataKey="dosage" fill={barFill} radius={[0, 3, 3, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      )}

      {categoryData.length > 0 && (
        <div>
          <h5 className="text-xs font-medium text-[var(--text-muted)] mb-2">药材分类分布</h5>
          <div className="flex flex-wrap gap-1.5">
            {categoryData.map((entry) => (
              <div key={entry.name} className="flex items-center gap-1.5 px-2 py-1 rounded-[var(--radius-pill)] text-xs" style={{ backgroundColor: `${entry.fill}15`, color: entry.fill }}>
                <div className="w-2 h-2 rounded-[var(--radius-pill)]" style={{ backgroundColor: entry.fill }} />
                <span>{entry.name}</span>
                <span className="opacity-70">{entry.value}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  )
}

/**
 * 配方卡片组件 — 用于卡片视图展示单个配方
 * Apple HIG 风格：清晰层级、充足呼吸空间、语义化颜色
 */
import { Link } from 'react-router-dom';
import { CheckCircle2, Eye, Star, ArrowRightLeft } from 'lucide-react';
import { cn } from '@/lib/utils';
import { Highlight } from '@/components/common';
import { StatusBadge, Badge, Card, CardContent } from '@/components/ui';
import type { Formula, FormulaStatus } from '@/types/formula';

function formatDate(dateStr: string): string {
  if (!dateStr) return '-';
  return new Date(dateStr).toLocaleDateString('zh-CN');
}

const STATUS_ACCENT: Record<string, string> = {
  approved:     'border-[var(--color-success)]',
  pending_review: 'border-[var(--color-warning)]',
  in_review:    'border-[var(--color-secondary)]',
  rejected:     'border-[var(--color-error)]',
  draft:        'border-[var(--border-color)] dark:border-neutral-700',
  archived:     'border-[var(--border-color)]',
  deprecated:   'border-[var(--border-color)]',
};

const STATUS_BG: Record<string, string> = {
  approved:     'bg-[var(--color-success-container)] dark:bg-[var(--color-success-container)]/20',
  pending_review: 'bg-[var(--color-warning-container)] dark:bg-[var(--color-warning-container)]/20',
  in_review:    'bg-[var(--color-secondary-container)] dark:bg-[var(--color-secondary-container)]/20',
  rejected:     'bg-[var(--color-error-container)] dark:bg-[var(--color-error-container)]/20',
  draft:        'bg-[var(--bg-tertiary)]/40',
  archived:     'bg-[var(--bg-tertiary)]/40',
  deprecated:   'bg-[var(--bg-tertiary)]/40',
};

const STATUS_BAR: Record<string, string> = {
  approved:     'bg-[var(--color-success-container)]0',
  pending_review: 'bg-[var(--color-warning-container)]0',
  in_review:    'bg-[var(--color-secondary-container)]0',
  rejected:     'bg-[var(--color-error-container)]0',
  draft:        'bg-neutral-300',
  archived:     'bg-[var(--border-color)]',
  deprecated:   'bg-[var(--border-color)]',
};

export function FormulaCard({
  formula,
  search,
  isFavorite,
  isSelected,
  onToggleFavorite,
  onToggleSelect,
  onPreview,
}: {
  formula: Formula;
  search: string;
  isFavorite: boolean;
  isSelected: boolean;
  onToggleFavorite: () => void;
  onToggleSelect: () => void;
  onPreview: () => void;
}) {
  const statusBg     = STATUS_BG[formula.status] || STATUS_BG.draft;
  const statusBar    = STATUS_BAR[formula.status] || STATUS_BAR.draft;
  const isFavOrSelected = isFavorite || isSelected;

  return (
    <Card className={cn(
      'group relative overflow-visible transition-all duration-200',
      'border border-[var(--border-color)] bg-[var(--bg-secondary)] shadow-sm',
      isSelected && 'ring-2 ring-[var(--color-primary-container)] dark:ring-[var(--color-primary)]',
      isFavOrSelected && statusBg,
    )}>
      {/* 顶部状态色条 */}
      <div className={cn('h-[3px] w-full rounded-t-xl', statusBar)} />

      <CardContent className="p-5">
        {/* 收藏按钮 */}
        <button
          onClick={(e) => { e.preventDefault(); e.stopPropagation(); onToggleFavorite(); }}
          className={cn(
            /* A-23：原 26×26（14px 图标 + p-1.5），未达 WCAG 2.5.5 的 44×44。
               撑到 44×44 作命中区，用 -m-[9px] 抵消，视觉位置与原来完全一致。 */
            'absolute top-[var(--space-apple-sm)] right-3 p-1.5 min-w-[44px] min-h-[44px] -m-[9px] inline-flex items-center justify-center rounded-[var(--radius-Apple-sm)] transition-all',
            isFavorite
              ? 'bg-[var(--color-warning-container)] text-[var(--color-warning-text)]0'
              : 'text-[var(--text-muted)] hover:bg-[var(--bg-secondary)] hover:text-[var(--color-warning-text)]',
          )}
          aria-label={isFavorite ? '取消收藏' : '收藏'}
          aria-pressed={isFavorite}
        >
          <Star size={14} className={isFavorite ? 'fill-warning-400 text-[var(--color-warning-text)]' : ''} />
        </button>

        {/* 多选框 */}
        <button
          onClick={(e) => { e.preventDefault(); e.stopPropagation(); onToggleSelect(); }}
          className="w-11 h-11 -m-3 rounded shrink-0 transition-all inline-flex items-center justify-center mt-0.5"
          aria-label={isSelected ? '取消选择' : '选择'}
          aria-pressed={isSelected}
        >
          {/* A-23：20×20 的视觉方框下沉到内层 span，外层 button 只作 44×44 命中区 */}
          <span
            className={cn(
              'w-5 h-5 rounded border-2 shrink-0 transition-all flex items-center justify-center',
              isSelected
                ? 'bg-primary-container border-[var(--color-primary)] text-[var(--color-primary)]'
                : 'border-[var(--border-color)]',
            )}
          >
            {isSelected && <CheckCircle2 size={14} strokeWidth={3} />}
          </span>
        </button>

        {/* 标题区 */}
        <div className="flex items-start justify-between mb-2 pl-7 pr-8">
          <div className="min-w-0 flex-1">
            <h3 className="text-sm font-semibold text-[var(--text-primary)] group-hover:text-[var(--color-primary-text)] dark:group-hover:text-[var(--color-primary-text)] transition-colors line-clamp-1 leading-snug">
              <Highlight text={formula.name} keyword={search} />
            </h3>
            <p className="text-xs text-[var(--text-muted)] mt-0.5 leading-relaxed">
              <Highlight text={formula.code || ''} keyword={search} /> · v{formula.version}
            </p>
          </div>
          <StatusBadge status={formula.status} />
        </div>

        {/* 描述 */}
        {formula.description && (
          <p className="text-xs text-[var(--text-muted)] line-clamp-2 mb-[var(--space-apple-sm)] leading-relaxed pl-7">
            {formula.description}
          </p>
        )}

        {/* 功效标签 */}
        {formula.targetEffects && formula.targetEffects.length > 0 && (
          <div className="flex flex-wrap gap-1.5 mb-[var(--space-apple-sm)] pl-7">
            {formula.targetEffects.slice(0, 3).map((effect: any) => (
              <Badge key={typeof effect === 'string' ? effect : effect.effectName} variant="primary" size="sm">
                {typeof effect === 'string' ? effect : effect.effectName}
              </Badge>
            ))}
            {formula.targetEffects.length > 3 && (
              <Badge variant="neutral" size="sm">
                +{formula.targetEffects.length - 3}
              </Badge>
            )}
          </div>
        )}

        {/* 底部信息 */}
        <div className="flex items-center justify-between pt-3 mt-1 border-t border-[var(--border-color)]">
          <span className="text-xs text-[var(--text-muted)]">{formatDate(formula.updatedAt)}</span>
          <div className="flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
            <button
              onClick={(e) => { e.preventDefault(); onPreview(); }}
              className="p-1.5 rounded-[var(--radius-Apple-sm)] hover:bg-[var(--bg-secondary)] text-[var(--text-muted)] hover:text-[var(--color-primary-text)] dark:hover:text-[var(--color-primary-text)] transition-colors"
              aria-label="快速预览"
            >
              <Eye size={14} />
            </button>
            <Link
              to={`/formulas/${formula.id}`}
              className="p-1.5 rounded-[var(--radius-Apple-sm)] hover:bg-[var(--bg-secondary)] text-[var(--text-muted)] hover:text-[var(--color-primary-text)] dark:hover:text-[var(--color-primary-text)] transition-colors"
              aria-label="查看详情"
            >
              <ArrowRightLeft size={14} />
            </Link>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}
